633: /// The TOTAL, order-independent ranking of two observations of the SAME window at an equal
634: /// instant, evaluated at `now`: (1) a known future reset beats a known past reset beats a missing
635: /// one (a past reset means the window is reset, whatever its share); (2) the higher
636: /// `used_percent`; (3) the later `resets_at`; (4) identical - either. `Greater` when `a` ranks
637: /// above `b`.
638: fn cmp_window_rank(
639:     a: (f64, Option<DateTime<FixedOffset>>),
640:     b: (f64, Option<DateTime<FixedOffset>>),
641:     now: DateTime<Utc>,
642: ) -> std::cmp::Ordering {
643:     let rank = |r: Option<DateTime<FixedOffset>>| match r {
644:         Some(t) if t.with_timezone(&Utc) > now => 2u8,
645:         Some(_) => 1,
646:         None => 0,
647:     };
648:     rank(a.1)
649:         .cmp(&rank(b.1))
650:         .then(a.0.clamp(0.0, 100.0).total_cmp(&b.0.clamp(0.0, 100.0)))
651:         .then(a.1.cmp(&b.1))
652: }
