654: /// The observation the thread/sub-agent aggregation keeps after seeing `b` ([`newer_wins`] for the
655: /// newer instant); at an EQUAL instant each window is merged on its own - the higher primary
656: /// `used_percent` (with its reset) and, independently, the higher secondary - so a fuller weekly
657: /// window is never hidden behind a fuller 5-hour one.
658: pub fn merge_observation(
659:     a: Option<Observation>,
660:     b: Option<&Observation>,
661:     now: DateTime<Utc>,
662: ) -> Option<Observation> {
663:     // an observation that names no (valid) window or has no instant is absent
664:     let usable = |o: &Observation| o.named() && o.at.is_some();
665:     let (av, bv) = match (a.as_ref().filter(|o| usable(o)), b.filter(|o| usable(o))) {
666:         (Some(av), Some(bv)) => (av, bv),
667:         (None, Some(bv)) => return Some(bv.clone()),
668:         _ => return a,
669:     };
670:     let key = |w: &Window| {
671:         (
672:             w.used_percent,
673:             w.resets_at
674:                 .as_deref()
675:                 .and_then(|r| DateTime::parse_from_rfc3339(r).ok()),
676:         )
677:     };
678:     // the newer observation replaces a window ONLY where its own is valid; the older one fills
679:     // the rest; at an equal instant each window takes the total rank
680:     let (newer, older) = if bv.at > av.at { (bv, av) } else { (av, bv) };
681:     let equal = av.at == bv.at;
682:     let pick = |n: &Option<Window>, o: &Option<Window>| match (n, o) {
683:         (Some(n), Some(o)) if equal => Some(
684:             if cmp_window_rank(key(n), key(o), now) != std::cmp::Ordering::Less {
685:                 n
686:             } else {
687:                 o
688:             }
689:             .clone(),
690:         ),
691:         (Some(n), _) => Some(n.clone()),
692:         (None, o) => o.clone(),
693:     };
